# inspect detector on test to confirm line axes and nodes
colors=set(v for row in gt for v in row)
for color in sorted(colors):
 rr=[r for r,row in enumerate(gt) if row.count(color)>=len(gt[0])-3]
 cc=[c for c in range(len(gt[0])) if sum(row[c]==color for row in gt)>=len(gt)-3]
 if rr and cc: print(color,rr,cc)
